import sys
from collections import defaultdict


def minutes(text):
    h, m = text.split(":")
    return int(h) * 60 + int(m)


def main():
    data = defaultdict(int)
    for line in sys.stdin:
        line = line.strip()
        if not line:
            continue
        name, start, end = line.split()
        start_min = minutes(start)
        end_min = minutes(end)
        if end_min < start_min:
            worked = (24 * 60 - start_min) + end_min
        elif start_min == end_min:
            worked = 0
        else:
            worked = end_min - start_min
        if worked > 6 * 60:
            if worked > 9 * 60:
                worked -= 45
            else:
                worked -= 30
        data[name] += worked

    for name in sorted(data.keys()):
        total_minutes = data[name]
        hours = total_minutes // 60
        minutes = total_minutes % 60
        print(f"{name} {hours:02d}:{minutes:02d}")


if __name__ == "__main__":
    main()
